import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.F7eQ-ohH.js";const i="/bzygq/assets/quesion_imgs_e5ec576c4983459dbff00f00e704ab56.C3973nbk.png",o="/bzygq/assets/quesion_imgs_51272dea97ee472891c44cd425453cc7.DEhflYEQ.png",l="/bzygq/assets/quesion_imgs_3b3efac54de2471abb07e281ed507b01.DDN9-S90.png",P="/bzygq/assets/quesion_imgs_15406a0a72584bd98fc869d22470345a.Du-4SYS6.png",h="/bzygq/assets/quesion_imgs_10c8eb8e17fe4a24a8aad4732090abb4.C7PrG9oP.png",n="/bzygq/assets/quesion_imgs_992af13d85534a6084aa4837070f8e1d.D1QU8-NC.png",s="/bzygq/assets/quesion_imgs_2d2f377c788043319f5090db83df8d2e.DOSUr_Br.png",I="/bzygq/assets/quesion_imgs_539dbcf4c0d74e97ae41a5a1cd5fdb5c.D2jVpgDz.png",p="/bzygq/assets/quesion_imgs_1e51f5fad0034cba917a59b21589aa38.6gAKeWgk.png",b="/bzygq/assets/quesion_imgs_d1b5850111904260a7a39bd909a47731.DEx2t6Qd.png",c="/bzygq/assets/quesion_imgs_cc5b0c33c2cc481491fa1f518a0f6d82.DCh2jr2K.png",g="/bzygq/assets/quesion_imgs_e68864d594a243038ba540a14a199f7c.B1HLsHqs.png",S=JSON.parse('{"title":"Part 06： 网络层","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/计算机网络/6、 网络层.md","filePath":"科技岗专业课/计算机网络/6、 网络层.md","lastUpdated":1788883925000}'),u={name:"科技岗专业课/计算机网络/6、 网络层.md"};function q(A,t,C,m,v,f){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="part-06-网络层" tabindex="-1"><strong>Part 06： 网络层</strong> <a class="header-anchor" href="#part-06-网络层" aria-label="Permalink to &quot;**Part 06： 网络层**&quot;">​</a></h1><table tabindex="0"><thead><tr><th>【原创声明】大家好，我是say，是这篇文章的原创作者！985硕士毕业，应届进入某大厂后道心破碎，社招上岸多家855半垄断央企，因为自己淋过雨，希望帮大家撑把伞，帮助更多同学找到不内卷、能够好好生活的央国企，已帮助1000+同学上岸央国企，需要连联系学长的加微信：wx_hxsay</th></tr></thead></table><h2 id="网络层功能" tabindex="-1">网络层功能 <a class="header-anchor" href="#网络层功能" aria-label="Permalink to &quot;网络层功能&quot;">​</a></h2><p>网络层是 OSI 参考模型中的第三层，主要负责将分组从源节点传输到目的节点，为传输层提供服务。其核心功能包括逻辑寻址、路由选择、分组转发、拥塞控制以及异构网络互联等，以确保数据在不同网络之间的正确传输和高效通信。</p><h2 id="网络层主要协议" tabindex="-1">网络层主要协议 <a class="header-anchor" href="#网络层主要协议" aria-label="Permalink to &quot;网络层主要协议&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><ol><li><strong>网际协议 IP</strong> ：负责网络层寻址、路由选择、分段及包重组，有 IPv4 和 IPv6 两个版本。IPv4 采用 32 位地址，以点分十进制表示；IPv6 采用 128 位地址，地址空间更大，能满足未来物联网等大量设备接入互联网的需求。IP 协议是一个无连接、不可靠的协议，其核心问题是路由选择 。</li><li><strong>地址解析协议 ARP</strong> ：负责把 IP 地址转化成物理地址 。</li><li><strong>反向地址解析协议 RARP</strong> ：负责把物理地址转化成 IP 地址 。</li><li><strong>网际控制报文协议 ICMP</strong> ：定义了网络层控制和传递消息的功能，可以报告 IP 数据包传送过程中发生的错误、失败等信息，提供网络诊断功能 。</li><li><strong>网际组管理协议 IGMP</strong> ：负责管理 IP 组播组 。</li><li><strong>路由信息协议 RIP</strong> ：是典型的距离向量算法 。</li><li><strong>开放式最短路径优先协议 OSPF</strong> ：是链路状态算法，用于让一个组织或运营商内部的所有路由器自动地、动态地学习到整个网络的拓扑，并计算出到达所有网段的最短路径</li></ol><h2 id="异构网络互联" tabindex="-1">异构网络互联 <a class="header-anchor" href="#异构网络互联" aria-label="Permalink to &quot;异构网络互联&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>指将不同类型、不同协议的网络连接在一起，实现数据在异构网络之间的传输。例如，将以太网、无线局域网、广域网等不同类型的网络连接起来。网络层通过 IP 协议将各种异构网络中的数据封装成统一格式的数据包，屏蔽了不同网络的差异，使得数据能够在不同网络之间透明传输。同时，网络层还需要处理不同网络之间的地址转换、协议转换等问题，以确保数据能够正确地到达目的节点。</p><h2 id="路由与转发" tabindex="-1">路由与转发 <a class="header-anchor" href="#路由与转发" aria-label="Permalink to &quot;路由与转发&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><p>路由器的主要功能包括路由选择和分组转发，根据所需的性能要求，采用合适的路由算法来构造路由表，并进行路由选择。该路由表会根据从各相邻路由器所得到的关于整个网络的拓补变化情况，动态的改变所选择的路由，最终得到最佳的路由。</p><h3 id="路由选择" tabindex="-1">路由选择 <a class="header-anchor" href="#路由选择" aria-label="Permalink to &quot;路由选择&quot;">​</a></h3><p>是指确定数据包从源节点到目的节点的最佳路径的过程。路由器根据网络拓扑结构、链路状态、路由协议等信息，构建路由表，其中包含了网络地址与下一跳地址的映射关系。当路由器接收到数据包时，会根据数据包中的目的地址查找路由表，确定将数据包转发到哪个下一跳节点，从而实现数据的定向传输。</p><h3 id="分组转发" tabindex="-1">分组转发 <a class="header-anchor" href="#分组转发" aria-label="Permalink to &quot;分组转发&quot;">​</a></h3><p>是指路由器根据路由表将接收到的数据包从一个接口转发到另一个接口的过程。当数据包到达路由器时，路由器会检查数据包的目的地址，然后在路由表中查找对应的转发条目，根据条目中指定的出接口将数据包转发出去。转发过程涉及到数据包的接收、检查、修改（如更新 TTL 字段）和发送等操作，需要高效、准确地完成，以保证数据的快速传输。</p><h2 id="网络层的主要设备" tabindex="-1">网络层的主要设备 <a class="header-anchor" href="#网络层的主要设备" aria-label="Permalink to &quot;网络层的主要设备&quot;">​</a></h2><p><img src="'+P+'" alt=""></p><p><strong>路由器（Router）</strong> ：用于连接多个逻辑上分开的网络，具有判断网络地址和选择 IP 路径的功能，是网络层的一种互联设备。它能在多网络互联环境中，建立灵活的连接，可用完全不同的数据分组和介质访问方法连接各种子网。路由器的核心功能包括对子网间的数据包进行路由选择，实现拥塞控制、网际互联等功能，确保数据从源主机到目的主机的端到端传输。关键协议包括 IP（网际协议）、ICMP（网络控制报文协议）、ARP（地址解析协议）等 。</p><p><strong>三层交换机（Layer 3 Switch）</strong> ：结合了二层交换机的高速转发与路由器的路由功能，主要用于同一局域网内不同 VLAN 间的通信。它可以基于 IP 地址在不同 VLAN 或子网间路由数据，替代部分路由器功能，通过硬件 ASIC 芯片实现三层路由，转发速率远超传统路由器，支持 VLAN 间路由、静态路由及部分动态路由协议（如 OSPFv2/v3） 。</p><p><strong>桥路器（Brouter）</strong> ：它控制从一个网络组件到另一个网络组件（时充当桥接器）和从网络到因特网（时充当路由器）的传输 。</p><p><strong>网关（Gateway）</strong> ：又称网间连接器、协议转换器，在网络层以上实现网络互连，是最复杂的网络互连设备，仅用于两个高层协议不同的网络互连。既可以用于广域网互连，也可以用于局域网互连。网关对收到的信息要重新打包，以适应目的系统的需求</p><h2 id="历年真题" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网（2022 年）】网络层的主要功能是（ ）。A. 将网络地址翻译成对应的物理地址，并决定如何将数据从发送方路由到接收方B. 提供端到端的可靠、不可靠服务，包括连接管理、流量控制、复用与分用C. 定义数据格式及加密D. 定义如何开始、控制和结束一个会话答案 ：A解析 ：网络层的核心功能是逻辑寻址、路由选择和分组转发，其主要作用是将网络地址（如 IP 地址）翻译成对应的物理地址（如网卡地址），并决定如何将数据从发送方路由到接收方</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2023 年）】以下关于网络层和数据链路层联网设备的描述，正确的是（ ）。A. 网络层的联网设备是路由器B. 数据链路层的联网设备是网桥和交换机C. 传输层和会话层主要是软件功能，都不需要专用的联网设备D. 以上都对答案 ：D解析 ：网络层的主要设备是路由器，负责根据 IP 地址进行路由选择和分组转发；数据链路层的常见设备包括网桥和交换机，它们基于 MAC 地址进行帧的转发和过滤；传输层和会话层主要通过软件实现，一般不需要专用的联网设备</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2014 年）】网络层提供的服务使传输层不需要了解网络中的（ ）。A. 数据传输和交换技术B. 物理地址C. 端口号D. 应用程序答案 ：A解析 ：网络层的目的是实现两个端系统之间的数据透明传送，为传输层提供服务，使传输层不需要了解网络中的数据传输和交换技术，如分组交换、路由选择等具体实现细节。</th></tr></thead></table><h2 id="ipv4协议" tabindex="-1">IPv4协议 <a class="header-anchor" href="#ipv4协议" aria-label="Permalink to &quot;IPv4协议&quot;">​</a></h2><h2 id="ipv4的概念" tabindex="-1">IPv4的概念 <a class="header-anchor" href="#ipv4的概念" aria-label="Permalink to &quot;IPv4的概念&quot;">​</a></h2><h3 id="ipv4地址概念" tabindex="-1">IPv4地址概念 <a class="header-anchor" href="#ipv4地址概念" aria-label="Permalink to &quot;IPv4地址概念&quot;">​</a></h3><p>IPv4 即互联网协议第四版，是互联网协议（IP）的一种具体实现，也是目前全球互联网广泛使用的网络层协议之一。它定义了网络上设备如何标识和通信，通过为每个连接到互联网的设备分配唯一的地址，实现数据在网络中的路由和传输，使得不同地区、不同类型的网络设备能够相互连接和交换信息。</p><h3 id="ipv4的特点" tabindex="-1">IPv4的特点 <a class="header-anchor" href="#ipv4的特点" aria-label="Permalink to &quot;IPv4的特点&quot;">​</a></h3><p>IPv4的特点通常包括唯一性、固定长度，可变性</p><ol><li>**唯一性：**在一个特定的网络环境中，每台设备的IPv4地址都是唯一的。这是确保网络中数据能够准确无误地发送到目标设备的关键。如同现实生活中的家庭住址，唯一性保证了网络数据包能够像信件一样准确地送达目的地，避免数据混乱和错误传输。</li><li>**固定长度：**IPv4地址的长度固定为32位。这种固定长度的设计使得网络设备在处理IPv4地址时能够采用统一的方式进行存储、解析和路由决策。它就像一个标准的容器，无论里面存储的是什么内容，其大小始终保持不变，便于网络设备进行高效的处理和管理。</li><li>**可变性：**计算机拥有的ip地址不是固定不变的，当网络发生变化之后，计算机的ip地址也会动态的发生变化，现在绝大多数计算机使用的都是动态ip地址。</li></ol><h3 id="ipv4的表示方法——点分十进制表示法" tabindex="-1">IPv4的表示方法——点分十进制表示法 <a class="header-anchor" href="#ipv4的表示方法——点分十进制表示法" aria-label="Permalink to &quot;IPv4的表示方法——点分十进制表示法&quot;">​</a></h3><p>由于32位二进制数不容易被人记忆，所以在书写IP地址的时候，通常采用点分十进制表示法，将 32 位的二进制地址分成 4 个 8 位的部分，每个部分用十进制数表示，中间用点号分隔。例如，192.168.1.1 就是一个典型的 IPv4 地址。其中，每个十进制数的取值范围是 0 到 255。这种表示方法便于人们理解和记忆，也方便网络设备进行地址的识别和处理。</p><table tabindex="0"><thead><tr><th>IP地址</th><th>11001100 11100011 10101011 11010011</th><th></th><th></th><th></th></tr></thead><tbody><tr><td>4 个字节</td><td>11001100</td><td>11100011</td><td>10101011</td><td>11010011</td></tr><tr><td>转化为十进制数</td><td>204</td><td>227</td><td>171</td><td>211</td></tr><tr><td>点分十进制表示</td><td>204.227.171.211</td><td></td><td></td><td></td></tr></tbody></table><p>例如将IP地址： 11001100 11100011 10101011 11010011用点分十进制表示法表示的转换过程如上表所示。</p><h2 id="ip数据报格式" tabindex="-1">IP数据报格式 <a class="header-anchor" href="#ip数据报格式" aria-label="Permalink to &quot;IP数据报格式&quot;">​</a></h2><p>IP数据报由首部和数据两部分组成，首部的长度一般在20~60字节之间，其中固定长度是20字节是所有IP数据报所必须的；在首部固定部分后面有一些是可选字段，其长度是可变的，一个IP数据报的最大长度为65535字节，以下是各部分及字段详细介绍：</p><h3 id="ip数据报首部" tabindex="-1">IP数据报首部 <a class="header-anchor" href="#ip数据报首部" aria-label="Permalink to &quot;IP数据报首部&quot;">​</a></h3><p><img src="'+h+'" alt=""></p><h4 id="固定部分-20字节" tabindex="-1">固定部分（20字节 ） <a class="header-anchor" href="#固定部分-20字节" aria-label="Permalink to &quot;固定部分（20字节 ）&quot;">​</a></h4><ol><li><strong>版本（4位）</strong>：标识IP协议版本，常见有IPv4（值为4 ）和IPv6（值为6 ） ，发送和接收设备据此确定处理方式。</li><li><strong>首部长度（4位）</strong>：以4字节为单位，指示IP数据报首部长度。因首部可变部分存在，需该字段确定首部边界，取值范围5 - 15（对应20 - 60字节 ）。</li><li><strong>区分服务（8位）</strong>：用于提供不同服务质量，前6位是服务类型（DSCP） ，可标识不同优先级或服务需求，后2位保留。</li><li><strong>总长度（16位）</strong>：指IP数据报（首部 + 数据部分）的总字节数，最大值65535字节 ，据此判断数据报大小。</li><li><strong>标识（16位）</strong>：源主机为数据报分配唯一标识，用于分片和重组。同一数据报分片具有相同标识，接收方据此判断哪些分片属同一数据报。</li><li><strong>标志（3位）</strong>：最高位保留，中间位DF（不分片） ，置1表示数据报不能分片；最低位MF（更多分片） ，置1表示后续还有分片，置0表示最后一个分片。</li><li><strong>片偏移（13位）</strong>：以8字节为单位，指示该分片在原数据报中的相对位置，用于重组分片数据报。</li><li><strong>生存时间（TTL，8位）</strong>：数据报在网络中可经过的最大跳数，每经一个路由器减1 ，减为0时丢弃，防止数据报在网络中无限循环。</li><li><strong>协议（8位）</strong>：标识数据部分封装的上层协议，如TCP（值为6 ）、UDP（值为17 ） ，使IP层能将数据交付给对应上层协议处理。</li><li><strong>首部检验和（16位）</strong>：仅对首部计算校验和，用于检测首部在传输过程中是否出错。计算方法是将首部按16位分组求和取反，接收方重新计算验证。</li><li><strong>源地址（32位）</strong>：发送方IP地址，标识数据报来源。</li><li><strong>目的地址（32位）</strong>：接收方IP地址，指示数据报最终目的地。</li></ol><h3 id="可变部分" tabindex="-1">可变部分 <a class="header-anchor" href="#可变部分" aria-label="Permalink to &quot;可变部分&quot;">​</a></h3><ol><li><strong>可选字段</strong>：长度可变，用于实现可选功能，如记录路由（记录数据报经过的路由器地址）、时间戳（记录数据报经过各路由器的时间） ，最长40字节。</li><li><strong>填充</strong>：可选字段长度不是4字节整数倍时，用填充字段补全，保证首部长度是4字节整数倍。</li></ol><h3 id="ip数据报数据部分" tabindex="-1">IP数据报数据部分 <a class="header-anchor" href="#ip数据报数据部分" aria-label="Permalink to &quot;IP数据报数据部分&quot;">​</a></h3><p>承载上层协议（如TCP、UDP）的数据，长度由总长度减去首部长度确定，其内容根据上层协议不同而不同，如TCP数据段、UDP用户数据报等。</p><h2 id="ipv4地址分类" tabindex="-1">IPv4地址分类 <a class="header-anchor" href="#ipv4地址分类" aria-label="Permalink to &quot;IPv4地址分类&quot;">​</a></h2><p>IP地址分类是指将IP地址划分成若干个固定的类，每一类地址都是由两个固定长度的字段组成的，两级的IP地址可以用网络号+主机号表示。</p><p><img src="'+n+'" alt=""></p><p>前面一部分是网络号，标志主机或者路由器所连接到的网络，网络号在整个互联网范围内是唯一的，第二个字段是主机号，标志着该主机路由器。由于前面的网络号在整个互联网范围是唯一的，因此整个IP地址在整个互联网范围也是唯一的，网络号相同的主机不经过路由器可以直接进行通信。</p><h3 id="_5类ip地址" tabindex="-1">5类IP地址 <a class="header-anchor" href="#_5类ip地址" aria-label="Permalink to &quot;5类IP地址&quot;">​</a></h3><p><img src="'+s+'" alt=""></p><p>IPv4 地址根据网络号和主机号的划分方式，主要分为以下五类：</p><h4 id="a类地址" tabindex="-1">A类地址 <a class="header-anchor" href="#a类地址" aria-label="Permalink to &quot;A类地址&quot;">​</a></h4><ul><li><strong>结构</strong>：首位固定为 0 ，紧接着 7 位为网络号，剩余 24 位为主机号 ，共 8 位用于标识网络，24 位标识主机。</li><li><strong>范围</strong>：网络号取值范围是 0 - 127 ，但 0 和 127 有特殊用途（如 127 用于本地环回测试 ），实际可用网络号从 1 - 126 。每个 A 类网络可容纳约 （减去全 0 和全 1 的主机号 ）个主机。</li><li><strong>用途</strong>：适用于大型网络，拥有大量主机的网络环境 。</li></ul><h4 id="b类地址" tabindex="-1">B类地址 <a class="header-anchor" href="#b类地址" aria-label="Permalink to &quot;B类地址&quot;">​</a></h4><ul><li><strong>结构</strong>：前两位固定为 10 ，接下来 14 位是网络号，16 位是主机号 ，即 16 位标识网络，16 位标识主机。</li><li><strong>范围</strong>：网络号取值范围从 128.0 - 191.255 。每个 B 类网络可容纳约 个主机。</li><li><strong>用途</strong>：适用于中等规模网络，像一些企业网络 。</li></ul><h4 id="c类地址" tabindex="-1">C类地址 <a class="header-anchor" href="#c类地址" aria-label="Permalink to &quot;C类地址&quot;">​</a></h4><ul><li><strong>结构</strong>：前三位固定为 110 ，21 位用于网络号，8 位用于主机号 ，也就是 24 位标识网络，8 位标识主机。</li><li><strong>范围</strong>：网络号取值范围从 192.0.0 - 223.255.255 。每个 C 类网络可容纳 = 254 个主机 。</li><li><strong>用途</strong>：常用于小型网络，如办公室、家庭网络 。</li></ul><h4 id="d类地址" tabindex="-1">D类地址 <a class="header-anchor" href="#d类地址" aria-label="Permalink to &quot;D类地址&quot;">​</a></h4><ul><li><strong>结构</strong>：前四位固定为 1110 ，剩余 28 位是多播地址 。</li><li><strong>范围</strong>：地址范围从 224.0.0.0 - 239.255.255.255 。</li><li><strong>用途</strong>：用于多播（组播）通信 ，可将数据同时发送给一组主机 。</li></ul><h4 id="e类地址" tabindex="-1">E类地址 <a class="header-anchor" href="#e类地址" aria-label="Permalink to &quot;E类地址&quot;">​</a></h4><ul><li><strong>结构</strong>：前四位固定为 1111 ，其余位保留为今后使用 。</li><li><strong>范围</strong>：地址范围从 240.0.0.0 - 255.255.255.255 。</li><li><strong>用途</strong>：目前主要用于研究和实验等特殊用途 。</li></ul><p>其中，A、B、C 类地址属于单播地址，用于一对一的通信场景 。</p><h2 id="特殊ip地址" tabindex="-1">特殊ip地址 <a class="header-anchor" href="#特殊ip地址" aria-label="Permalink to &quot;特殊ip地址&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特殊IP地址</th><th>地址范围/具体地址</th><th>用途</th></tr></thead><tbody><tr><td>受限广播地址</td><td>255.255.255.255</td><td>向本地网络内所有主机发送广播消息，路由器禁止转发</td></tr><tr><td>直接广播地址</td><td>主机号全为1，如C类地址网络号部分+255（不同类别网络号规则不同）</td><td>向同一子网内所有主机发送广播数据，路由器可决定是否转发</td></tr><tr><td>环回地址</td><td>127.0.0.0 - 127.255.255.255，常用127.0.0.1</td><td>测试本地TCP/IP协议是否正常工作，数据包不离开设备</td></tr><tr><td>0.0.0.0</td><td>无特定范围</td><td>设备启动未获取IP地址时，用作数据包源地址，不能作为目的地址</td></tr><tr><td>多播地址</td><td>224.0.0.0 - 239.255.255.255</td><td>实现一对多通信，用于视频流、在线会议、路由协议等</td></tr><tr><td>私有地址</td><td>A类：10.0.0.0 - 10.255.255.255B类：172.16.0.0 - 172.31.255.255C类：192.168.0.0 - 192.168.255.255</td><td>用于企业等内部网络，接入Internet需通过NAT转换</td></tr></tbody></table><h2 id="ip地址和物理地址区别" tabindex="-1">IP地址和物理地址区别 <a class="header-anchor" href="#ip地址和物理地址区别" aria-label="Permalink to &quot;IP地址和物理地址区别&quot;">​</a></h2><p>IP地址放在IP数据报的首部，是一种网络层以及以上层次所使用的地址，是一种逻辑地址；而物理地址则是放在MAC帧的首部，是数据链路层和物理层的使用地址。</p><ol><li><strong>IP地址（逻辑地址）</strong>：由网络层（IP协议）分配的逻辑地址，用于标识网络中设备的逻辑位置，可根据网络拓扑变化动态调整。IPv4为32位二进制数（通常表示为点分十进制，如192.168.1.1），IPv6为128位（如2001:0db8:85a3:0000:0000:8a2e:0370:7334）。</li><li><strong>物理地址（MAC地址）</strong>：由数据链路层（如以太网）使用的硬件地址，固化在网络接口卡（NIC）的芯片中，唯一标识设备的物理身份，通常不可修改。格式是48位二进制数，通常表示为12位十六进制数（如00:1A:2B:3C:4D:5E），前24位为厂商标识符（OUI），后24位为设备序列号。</li></ol><p>IP地址和物理地址的对比如下表所示：</p><table tabindex="0"><thead><tr><th>维度</th><th>IP地址</th><th>物理地址（MAC地址）</th></tr></thead><tbody><tr><td>所属层次</td><td>网络层（OSI第3层）</td><td>数据链路层（OSI第2层）</td></tr><tr><td>地址性质</td><td>逻辑地址，可动态分配或修改</td><td>物理地址，硬件固化，全球唯一</td></tr><tr><td>作用范围</td><td>跨网络路由（全球或局域网）</td><td>局域网内通信（同一数据链路层）</td></tr><tr><td>地址长度</td><td>IPv4：32位；IPv6：128位</td><td>48位（6字节）</td></tr><tr><td>分配方式</td><td>手动配置、DHCP动态分配或自动生成</td><td>由硬件厂商烧录，遵循IEEE标准</td></tr><tr><td>是否可变</td><td>可随网络环境变化（如更换路由器）</td><td>固定不变（除非更换网卡）</td></tr></tbody></table><p>两者在网络通信中缺一不可：IP地址实现逻辑路由，MAC地址完成物理传输，共同构成从“逻辑定位”到“物理送达”的完整通信链条。</p><h2 id="历年真题-1" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题-1" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【南方电网（2024 ）】以下 IP 地址中，属于 C 类地址的是（ ）。A. 112.213.12.23B. 210.123.23.12C. 23.123.213.23D. 156.123.32.12答案 ：B解析 ：C 类地址的二进制表示开头部分为 110，其 IP 范围是 192 - 223。A 选项和 C 选项是 A 类 IP 地址（二进制表示开头部分为 0，IP 范围是 1 - 126），D 选项是 B 类 IP 地址（二进制表示开头部分为 10，IP 范围是 128 - 191）</th></tr></thead></table><h2 id="划分子网和子网掩码" tabindex="-1">划分子网和子网掩码 <a class="header-anchor" href="#划分子网和子网掩码" aria-label="Permalink to &quot;划分子网和子网掩码&quot;">​</a></h2><h2 id="划分子网" tabindex="-1">划分子网 <a class="header-anchor" href="#划分子网" aria-label="Permalink to &quot;划分子网&quot;">​</a></h2><p>前面讲过，ip地址由网络号+主机号组成，而划分子网则是在IP地址中增加一个“子网段号”，是的两级的IP地址变成三级的IP地址。具体来说就是将主机号中的若干位划分为子网号，而网络号保持不变，如下图所示：</p><p><img src="'+I+'" alt=""></p><p>划分子网一般而言是一个局域网系统内部的失去，本局域网以外的单位是察觉不到这个网络内部是由多个子网组成的，对外仍然表现为一个网络。</p><p>当其它网络上的主机向该网络发送数据包的时候，IP数据包仍然根据网络号来查找路由器，路由器收到该IP数据包之后，再将其转换成局域网内部的子网号和真实的IP地址。</p><h2 id="子网掩码" tabindex="-1">子网掩码 <a class="header-anchor" href="#子网掩码" aria-label="Permalink to &quot;子网掩码&quot;">​</a></h2><p>子网掩码是一种用于标识 IP 地址中网络部分和主机部分的重要工具，在计算机网络中起着关键作用，子网掩码是一个 32 位的二进制数，它与 IP 地址结合使用，用于确定 IP 地址的网络部分和主机部分。P 地址和子网掩码是相辅相成的，缺一不可。IP 地址用于标识网络中的主机，而子网掩码用于确定 IP 地址的网络部分和主机部分。只有同时知道 IP 地址和子网掩码，才能确定该主机所在的网络以及在该网络中的具体位置。</p><p>将 IP 地址与子网掩码进行按位逻辑与运算，可以得到该 IP 地址所在的网络地址。例如，IP 地址为 192.168.1.100，子网掩码为 255.255.255.0，进行与运算后得到网络地址 192.168.1.0。同时通过改变子网掩码中 1 的位数，可以将一个较大的网络划分为多个较小的子网。例如，一个 C 类网络（默认子网掩码为 255.255.255.0），如果将子网掩码改为 255.255.255.192（即 26 位网络位），则可以将该网络划分为 4 个子网，每个子网可容纳 62 台主机。</p><p>路由器根据子网掩码来确定数据包的转发路径。当路由器接收到一个数据包时，它会根据数据包的目的 IP 地址和子网掩码来确定该数据包应该转发到哪个子网，常见的子网掩码如下所示：</p><ul><li>A 类网络：默认子网掩码为 255.0.0.0，网络部分占 8 位，主机部分占 24 位，适用于大型网络。</li><li>B 类网络：默认子网掩码为 255.255.0.0，网络部分占 16 位，主机部分占 16 位，适用于中型网络。</li><li>C 类网络：默认子网掩码为 255.255.255.0，网络部分占 24 位，主机部分占 8 位，适用于小型网络。</li></ul><h2 id="子网掩码计算方法" tabindex="-1">子网掩码计算方法 <a class="header-anchor" href="#子网掩码计算方法" aria-label="Permalink to &quot;子网掩码计算方法&quot;">​</a></h2><h3 id="网络地址计算" tabindex="-1">网络地址计算 <a class="header-anchor" href="#网络地址计算" aria-label="Permalink to &quot;网络地址计算&quot;">​</a></h3><p>将 IP 地址和子网掩码转换为二进制数，然后进行按位逻辑与运算，得到的结果就是网络地址。例如，IP 地址为 10.1.2.3，子网掩码为 255.255.255.0，转换为二进制后分别为：</p><ul><li>IP 地址：00001010.00000001.00000010.00000011</li><li>子网掩码：11111111.11111111.11111111.00000000</li><li>与运算结果：00001010.00000001.00000010.00000000，即网络地址为 10.1.2.0。</li></ul><h3 id="主机数量计算" tabindex="-1">主机数量计算 <a class="header-anchor" href="#主机数量计算" aria-label="Permalink to &quot;主机数量计算&quot;">​</a></h3><p>根据子网掩码中 0 的位数来计算主机数量。，其中减 2 是因为要排除网络地址和广播地址。例如，子网掩码为 255.255.255.192（即 26 位网络位，6 位主机位），则</p><h3 id="确定子网范围" tabindex="-1">确定子网范围 <a class="header-anchor" href="#确定子网范围" aria-label="Permalink to &quot;确定子网范围&quot;">​</a></h3><p>已知网络地址和子网掩码，可以确定该子网的 IP 地址范围。例如，网络地址为 192.168.1.0，子网掩码为 255.255.255.192，则该子网的 IP 地址范围为 192.168.1.1 到 192.168.1.62，广播地址为 192.168.1.63。</p><h2 id="无分类编址cidr" tabindex="-1">无分类编址CIDR <a class="header-anchor" href="#无分类编址cidr" aria-label="Permalink to &quot;无分类编址CIDR&quot;">​</a></h2><p>CIDR，即“无类域间路由（Classless Inter-Domain Routing）”，是一种TCP/IP协议中的路由聚合技术，可以减少IP地址的浪费和网络设备的压力，提高网络运行效率，是为了解决IP地址耗尽所提出的一种方法。CIDR 是一种摒弃传统 A、B、C 类网络划分模式的 IP 地址编址方法，通过 “网络前缀 + 主机位” 的方式灵活定义网络范围，实现 IP 地址的高效分配与路由聚合，解决了 IPv4 地址短缺和路由表膨胀问题。CIDR的主要特点包括：</p><ol><li><strong>无类别划分</strong> 不再依赖固定的 A 类（8 位网络位）、B 类（16 位）、C 类（24 位）网络边界，而是用 “/ 网络前缀长度” 表示网络范围。例如：</li></ol><ul><li>192.168.1.0/24 表示网络前缀为前 24 位，剩余 8 位为主机位。</li><li>10.0.0.0/16 表示前 16 位为网络前缀，后 16 位为主机位。</li></ul><ol><li><strong>地址表示法</strong></li></ol><ul><li>格式：IP地址/网络前缀长度，其中前缀长度用数字 n 表示（n 范围 1~32）。</li><li>示例：</li><li>子网掩码255.255.255.0对应/24（前 24 位为 1）；</li><li>子网掩码255.255.0.0对应/16（前 16 位为 1）。</li></ul><p>总之，CIDR通过调整前缀长度，将大网络划分为不同规模的子网，提高地址利用率。解决了 IPv4 地址资源紧张和路由效率问题，是现代网络编址的核心技术。掌握 CIDR 的地址计算和路由聚合方法，对网络规划、IP 地址管理及路由配置具有关键意义。</p><h2 id="历年真题-2" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题-2" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网（2017）】某公司的网络地址为 192.168.1.0，要划分成 5 个子网，每个子网最多 20 台主机，则适用的子网掩码是（）A. 255.255.255.192B. 255.255.255.240C. 255.255.255.224D. 255.255.255.248答案：C解析：需要划分成 5 个子网，2^3 = 8 &gt; 5，所以子网位至少需要 3 位；每个子网最多 20 台主机，2^5 - 2 = 30 &gt; 20，所以主机位至少需要 5 位。因此，子网掩码为 255.255.255.224。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网 （2016 ）】下列关于 IP 地址和子网掩码的说法中，正确的是（）A. IP 192.168.0.55 / 29 与 192.168.0.49 / 29 在同一子网B. 129.23.144.16 / 255.255.192.0 与 129.23.126.222 / 255.255.192.0 在同一子网C. 子网掩码为 255.255.255.192 的网段最多有 126 台可用的主机D. 子网掩码为 255.255.255.128 的网段最多有 126 台可用的主机答案：AD解析：/29 子网掩码对应 255.255.255.248，每个子网有 8 个 IP 地址，192.168.0.49 - 192.168.0.55 均在 49 - 56 网段，故 A 正确；255.255.192.0 的子网划分中，144 属于 128 - 191 网段，126 属于 0 - 127 网段，不在同一子网，B 错误；255.255.255.192 子网主机数为 62，C 错误；255.255.255.128 子网主机数为 126，D 正确</th></tr></thead></table><h2 id="路由协议" tabindex="-1">路由协议 <a class="header-anchor" href="#路由协议" aria-label="Permalink to &quot;路由协议&quot;">​</a></h2><p>路由协议是网络层的重要组成部分，用于确定数据包在网络中的传输路径。根据网络类型和设计需求，路由协议可分为不同的类型，主要包括路由选择协议、RIP、OSPF 和 BGP等协议。</p><h2 id="路由选择协议" tabindex="-1">路由选择协议 <a class="header-anchor" href="#路由选择协议" aria-label="Permalink to &quot;路由选择协议&quot;">​</a></h2><p><img src="'+p+'" alt=""></p><p>路由选择协议说白了就是网络里的“导航系统”，专门告诉路由器怎么把数据包从起点送到终点。比如说咱们寄快递，不同快递公司有不同的送货路线规划，路由选择协议也一样，根据网络大小和需求分成外部网关协议和内部网关协议两类：</p><ol><li>内部网关协议（IGP）：用于自治系统（AS）内部的路由信息交换，常见协议包括 RIP、OSPF、IS-IS 等。</li><li>外部网关协议（EGP）：用于不同自治系统之间的路由信息传递，目前最常用的是 BGP。</li></ol><p>举个例子：在一个公司或者机构内部的网络里（专业叫自治系统，AS），用的是“内部导航协议，IGP”，像RIP和OSPF就是属于内部网关协议。RIP比较简单粗暴，就看“跳数”——比如从A路由器到B路由器要经过几个中间设备，超过15步就觉得太远不去了，适合小网络，但反应慢，万一网络结构变了，它得好久才能更新路线，还容易绕路。OSPF就高级点，像画地图一样，把每个路由器的连接情况和带宽都记下来，用算法算出最快的路，适合大公司的复杂网络，还能分区管理，不会绕路，反应也快。</p><p>而不同公司、不同运营商的网络之间（比如电信和联通的网络），就得用“跨区导航协议，EGP”，最常用的是BGP。这就像不同快递公司之间交换送货信息，BGP不光看路有多远，还看“规矩”——比如经过哪些运营商、有没有政策限制，甚至可以自己设置优先走哪条路，特别适合像互联网这种超级复杂的大网络，能处理海量的路线信息，而且可以按策略控制数据走哪条线，比如优先选便宜的或者速度快的路径。</p><h2 id="路由信息协议-rip-routing-information-protocol" tabindex="-1">路由信息协议（RIP，Routing Information Protocol） <a class="header-anchor" href="#路由信息协议-rip-routing-information-protocol" aria-label="Permalink to &quot;路由信息协议（RIP，Routing Information Protocol）&quot;">​</a></h2><p>RIP（Routing Information Protocol，<strong>路由信息协议</strong>）是基于<strong>距离矢量算法</strong>的内部网关协议（IGP），核心用 “跳数” 衡量路径开销，仅适用于小型局域网或简单分支网络，是早期网络中常用的路由协议。通俗来说RIP协议就像个“路痴版导航”，是路由器里最简单的路径规划方式。打个比方，它就像你问邻居“去超市怎么走”，邻居告诉你“过3个路口左转”，你再把这话传给下一个人，大家靠互相打听来记路线，其核心流程如下：</p><p><img src="'+b+'" alt=""></p><ol><li>路由器初始化：启动时，仅包含自身直连网络的路由条目，形成初始路由表。</li><li>路由更新：每隔 30 秒，向邻居发送完整路由表（RIPv1）或增量更新（RIPv2），告知邻居自己可达的网络及跳数。</li><li>路径计算：收到邻居的路由信息后，对比自身路由表，选择跳数最少的路径作为最优路由，更新本地路由表。</li><li>环路处理：若某条路由不可达，通过 “毒性逆转” 标记为 16 跳（不可达），并快速通告邻居，避免环路。</li></ol><p>RIP协议的优点在于配置和维护门槛低，无需复杂拓扑规划，路由器无需存储全网拓扑，仅需维护邻居路由信息，对硬件要求低。RIP协议的缺点是，适用范围窄，最大 15 跳限制，无法用于中型及以上网络。逐跳更新导致路由信息扩散延迟，网络故障后恢复时间长。开销较大，30 秒全量广播（RIPv1）会占用网络带宽，尤其在路由器较多时。路径判断单一，仅看跳数，不考虑带宽、延迟等实际链路质量，可能选择低效路径。</p><p>RIP 协议的核心价值是 “简单易用”，适配小型网络的路由需求，但受限于跳数限制和收敛速度，如今已逐渐被 OSPF、EIGRP 等更高效的路由协议替代。其本质是 “邻居间共享全部路由”，通过跳数判断最优路径，是理解距离矢量路由协议的基础。</p><h2 id="开放式最短路径优先-ospf-open-shortest-path-first" tabindex="-1">开放式最短路径优先（OSPF，Open Shortest Path First） <a class="header-anchor" href="#开放式最短路径优先-ospf-open-shortest-path-first" aria-label="Permalink to &quot;开放式最短路径优先（OSPF，Open Shortest Path First）&quot;">​</a></h2><p>OSPF（Open Shortest Path First）是基于<strong>链路状态算法</strong>的企业级内部网关协议（IGP），核心用于大中型网络的路由寻址，凭借全局拓扑感知、最优路径计算和快速收敛成为主流选择。</p><p>通俗来说，OSPF协议就像个“聪明的城市交通规划师”，专门给中大型网络算最优路线，就像你用手机导航APP，每个路口的摄像头（路由器）实时上传路况，APP后台把所有路况拼成实时地图，然后根据你的起点和终点，直接算出最快路线，还能避开拥堵。OSPF就是这个逻辑，只不过它在网络里干的是同样的事儿——用实时链路状态算最优路径，还支持“选路优先看带宽”（比如优先走宽的路，不看跳数），是企业中大型网络的主流协议。主要工作流程如下：</p><ol><li>邻居发现与邻接建立：路由器启动后，向直连接口发送 Hello 包，匹配参数一致的设备建立邻居关系，进一步同步链路信息形成邻接关系。</li><li>链路状态同步：邻接路由器间交换 LSA（包含自身直连链路、邻居信息、Cost 值等），所有路由器收集 LSA 后，构建完全一致的 “链路状态数据库（LSDB）”（即全网拓扑图）。</li><li>最优路径计算：基于 LSDB，以自身为根节点，通过 SPF 算法生成 “最短路径树”，从树中提取路由条目写入本地路由表。</li><li>路由维护：链路故障或拓扑变化时，触发 LSA 更新，全网 LSDB 快速同步后，路由器重新执行 SPF 算法，更新路由表（收敛速度快）。</li></ol><p>OSPF协议的优点在于：路径最优，基于带宽计算 Cost，避免 RIP “跳数少但带宽低” 的低效路径。收敛快速,触发式更新 + SPF 算法，网络故障后能快速恢复路由连通。支持大型网络,区域划分降低路由开销，可适配千台路由器的复杂拓扑。开销可控，仅传递链路状态变化信息，不重复发送全量路由表，节省带宽。OSPF协议的缺点在于，配置复杂，区域规划、邻居管理、认证配置等要求运维具备一定技术门槛。资源占用高，需存储 LSDB 并执行 SPF 算法，对路由器的 CPU、内存要求高于 RIP。</p><p>OSPF 的核心竞争力是 “全局拓扑 + 最优路径 + 快速收敛”，通过区域划分突破了大型网络的扩展限制，是企业级网络（如园区网、数据中心互联）的首选 IGP 协议；其本质是 “全网同步拓扑，各自计算路由”，与 RIP“邻居共享路由，逐跳传递” 的逻辑形成核心区别。</p><h2 id="外部网关协议-bgp-border-gateway-protocol" tabindex="-1">外部网关协议（BGP，Border Gateway Protocol） <a class="header-anchor" href="#外部网关协议-bgp-border-gateway-protocol" aria-label="Permalink to &quot;外部网关协议（BGP，Border Gateway Protocol）&quot;">​</a></h2><p>BGP（Border Gateway Protocol）是<strong>外部网关协议（EGP）</strong> 的核心标准，核心用于不同自治系统（AS）间交换路由信息，凭借灵活的路由控制能力和防环路设计，成为互联网骨干网及企业跨 AS 互联的首选协议。</p><p>通俗来说BGP协议就像互联网世界的“跨国物流调度中心”，专门解决不同网络运营商（比如电信、联通、亚马逊云）之间的数据传输路线问题，比前面的OSPF和RIP更像“老油条”，讲究“策略优先”而非单纯找最短路径。 因为整个互联网是无数个运营商、企业网络连起来的“超级网”，每个主体都有自己的利益和规则（比如有的运营商之间互相免费转接流量，有的需要收费），BGP能让每个网络根据自己的策略选择路线，同时又能把所有路线信息互通，确保数据能跨全球传输，是互联网的“全球物流总指挥”。BGP的核心逻辑如下：</p><ol><li>对等体建立：手动配置对等体 AS 号和 IP 地址后，双方通过 TCP 端口 179 建立连接，发送 “OPEN 报文” 协商参数（如 AS 号、保持时间），参数一致则建立稳定邻居关系。</li><li>路由交换：邻居建立后，交换 “路由更新报文”，包含可达网络前缀及对应的 AS 路径、下一跳等属性，双方接收后更新本地 “BGP 路由表”。</li><li>最优路径选择：基于预设的路径属性优先级（如先比本地优先级，再比 AS 路径长度等），从多条可达路由中筛选出最优路由，若该路由需向内网发布，会注入 AS 内部 IGP。</li><li>路由维护：通过 “Keepalive 报文”（默认 60 秒发送一次）保活邻居关系；路由状态变化（如链路故障、策略调整）时，触发增量更新，同步对等体并重新决策最优路径。</li></ol><p>BGP协议的优点在于，唯一能支撑大规模跨 AS 互联的协议，是互联网全球互通的基础，通过多路径属性和路由策略，可按需控制流量走向（如优先走低成本运营商、分担流量），AS 路径属性 + 多种辅助防环机制，彻底避免跨 AS 路由环路。适配大规模网络，支持海量路由条目（互联网级路由表），更新机制高效，带宽开销可控。BGP协议的缺点是，配置复杂，对等体规划、路由策略设计、属性调整等对运维技术要求极高，需熟悉跨 AS 网络架构。依赖 IGP 支撑，BGP 对等体间的连通性需依赖 AS 内部 IGP 保障，若 IGP 故障会导致 BGP 邻居中断。选路决策复杂，多路径属性的优先级配置不当易导致路由异常，排查难度高于 IGP。</p><p>BGP 的核心竞争力是 “跨 AS 选路 + 灵活路由控制”，通过路径属性和 TCP 可靠连接，既保障了大规模互联的稳定性，又能满足企业个性化的流量调度需求，是互联网及中大型企业跨域互联的 “基石协议”。与 IGP（如 OSPF）的核心区别在于：IGP 负责 AS 内部 “快速收敛、最优路径”，BGP 负责 AS 之间 “策略控制、环路避免”。</p><h2 id="rip、ospf、bgp协议核心对比表" tabindex="-1">RIP、OSPF、BGP协议核心对比表 <a class="header-anchor" href="#rip、ospf、bgp协议核心对比表" aria-label="Permalink to &quot;RIP、OSPF、BGP协议核心对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比维度</th><th>RIP（路由信息协议）</th><th>OSPF（开放式最短路径优先）</th><th>BGP（边界网关协议）</th></tr></thead><tbody><tr><td>协议类型</td><td>内部网关协议（IGP），距离矢量协议</td><td>内部网关协议（IGP），链路状态协议</td><td>外部网关协议（EGP），路径矢量协议</td></tr><tr><td>核心定位</td><td>小型自治系统（AS）内部路由互联</td><td>大中型自治系统（AS）内部路由互联</td><td>跨自治系统（AS）路由交换（互联网/企业跨域）</td></tr><tr><td>算法基础</td><td>距离矢量算法（逐跳传递路由表）</td><td>链路状态算法 + SPF（最短路径优先）算法</td><td>路径矢量算法（传递路由属性+AS路径）</td></tr><tr><td>度量值（路径开销）</td><td>跳数（最大15跳，16跳不可达）</td><td>Cost=10⁸/链路带宽（bps），带宽越高Cost越小</td><td>无固定度量值，依赖多路径属性（AS路径长度、本地优先级等）</td></tr><tr><td>适用场景</td><td>小型局域网（如办公室、小型分支），无复杂拓扑</td><td>企业园区网、数据中心、大中型内网，需最优路径和快速收敛</td><td>互联网骨干网、企业多运营商互联、跨地域跨AS互联</td></tr><tr><td>收敛速度</td><td>慢（逐跳更新，依赖计时器）</td><td>快（触发式更新+SPF算法，秒级收敛）</td><td>中等（触发+增量更新，依赖对等体同步）</td></tr><tr><td>更新机制</td><td>周期全量更新（RIPv1广播，RIPv2组播），默认30秒</td><td>触发更新（链路变化时）+ Hello包保活（10/30秒），无全量路由广播</td><td>触发更新+增量更新，仅传递变化路由，Keepalive保活（60秒）</td></tr><tr><td>防环路机制</td><td>水平分割、毒性逆转、抑制计时器</td><td>SPF算法天然无环路，LSDB全网一致</td><td>AS路径属性（含自身AS则丢弃）、同步规则</td></tr><tr><td>支持核心功能</td><td>RIPv2支持VLSM、CIDR，无路由汇总优先级</td><td>支持VLSM、CIDR、路由汇总、认证、区域划分</td><td>支持路由策略（过滤/聚合/属性调整）、VPN、多协议（IPv4/IPv6）</td></tr><tr><td>资源占用（CPU/内存）</td><td>低（无需存储拓扑，仅维护邻居路由）</td><td>中高（需存储LSDB，执行SPF算法）</td><td>高（需维护海量路由表+路径属性，依赖TCP连接）</td></tr><tr><td>配置复杂度</td><td>简单（仅需启用协议、宣告直连网络）</td><td>中等（区域规划、接口配置、邻居匹配）</td><td>复杂（对等体规划、路由策略、属性调整）</td></tr><tr><td>典型版本</td><td>RIPv1（有类）、RIPv2（无类）</td><td>OSPFv2（IPv4）、OSPFv3（IPv6）</td><td>BGPv4（IPv4）、BGPv4+（IPv6）、MP-BGP（多协议）</td></tr></tbody></table><h2 id="历年真题-3" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题-3" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【南方电网（2024 ）】开放最短路径优先（OSPF）协议是一种链路状态路由协议，旨在替代距离矢量路由协议 RIP。OSPF 是一种无类路由协议，它使用区域概念实现可扩展性。RFC 2328 将 OSPF 度量定义为一个独立的值，该值称为开销，使用以下哪种作为 OSPF 开销度量？A. 跳数；B. 带宽；C. 延迟；D. 可靠性答案 ：B解析 ：OSPF 使用带宽作为开销度量，因为带宽能够更准确地反映链路的性能</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2023 ）】如果路由器收到了多个路由协议转发的关于某个目标的多条路由，那么决定采用哪条路由的策略是？A. 选择与自己路由协议相同的；B. 选择路由费用最小的；C. 比较各个路由的管理距离；D. 比较各个路由协议的版本答案 ：C解析 ：当路由器收到多个路由协议转发的关于某个目标的多条路由时，应该选择管理距离最短的路由，因为管理距离反映了路由协议的可信度和优先级。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2017 ）】以下哪些是有类路由协议？A. RIPV；B. IGRP；C. OSPF；D. IS - IS答案 ：AB解析 ：有类路由协议是指在路由更新中不包含子网掩码信息的协议，RIPV 和 IGRP 属于有类路由协议，而 OSPF 和 IS - IS 是无类路由协议。</th></tr></thead></table><h2 id="其它协议" tabindex="-1">其它协议 <a class="header-anchor" href="#其它协议" aria-label="Permalink to &quot;其它协议&quot;">​</a></h2><h2 id="arp协议" tabindex="-1">ARP协议 <a class="header-anchor" href="#arp协议" aria-label="Permalink to &quot;ARP协议&quot;">​</a></h2><h3 id="arp协议概念" tabindex="-1">ARP协议概念 <a class="header-anchor" href="#arp协议概念" aria-label="Permalink to &quot;ARP协议概念&quot;">​</a></h3><p>ARP即地址解析协议（Address Resolution Protocol ） ，是TCP/IP协议族中的重要协议，用于在采用以太网的TCP/IP网络中，将网络层的IPv4地址动态映射为数据链路层的MAC地址 。它仅适用于IPv4，IPv6中类似功能由ICMPv6的邻居发现协议实现。其主要作用是让网络设备能建立目标IP地址和MAC地址之间的映射，以便在局域网中准确传输数据帧。</p><p><img src="'+c+'" alt=""></p><h3 id="arp协议工作原理" tabindex="-1">ARP协议工作原理 <a class="header-anchor" href="#arp协议工作原理" aria-label="Permalink to &quot;ARP协议工作原理&quot;">​</a></h3><ol><li><strong>ARP缓存查找</strong> ：当设备要向目标设备发送数据时，先在本地ARP缓存表中查找目标IP地址对应的MAC地址。若存在，直接使用该MAC地址封装数据帧并发送；若不存在，则进入下一步。</li><li><strong>发送ARP请求</strong> ：设备以广播形式发送ARP请求报文，该报文封装在数据帧中。数据帧的源MAC地址是发送设备自身MAC地址，目的MAC地址为广播地址（FF - FF - FF - FF - FF - FF ） 。ARP请求报文中包含源IP地址、源MAC地址、目的IP地址等信息 。该请求会在整个局域网内传播，所有主机都会收到。</li><li><strong>ARP响应</strong> ：局域网内其他主机收到ARP请求后，检查报文中的目的IP地址是否与自身IP地址匹配。若不匹配，直接丢弃；若匹配，则将ARP报文中的源MAC地址和源IP地址信息记录到自己的ARP缓存表中 ，然后以单播方式向发送方返回ARP响应报文，报文中包含自身MAC地址。</li><li><strong>更新ARP缓存</strong> ：发送方收到ARP响应后，获取目标设备的MAC地址，将其与目标IP地址的映射关系存入本地ARP缓存表，后续与该目标设备通信时，可直接从缓存表中获取MAC地址，无需再次发送ARP请求 。ARP缓存表中的映射关系有一定有效期，过期后会自动删除。</li></ol><h3 id="rarp协议" tabindex="-1">RARP协议 <a class="header-anchor" href="#rarp协议" aria-label="Permalink to &quot;RARP协议&quot;">​</a></h3><p>RARP即逆向地址解析协议（Reverse Address Resolution Protocol ） ，于1984年6月在RFC903中定义 。与ARP相反，它的作用是将数据链路层的MAC地址动态映射为网络层的协议地址（如IP地址 ） 。在无盘工作站等场景中应用，这些设备知道自身MAC地址，但启动时不知道IP地址，通过RARP协议，无盘工作站发送RARP请求，网络中的RARP服务器接收请求后，根据MAC地址查找并返回对应的IP地址，使无盘工作站获得IP地址进行网络通信。</p><h2 id="icmp协议" tabindex="-1">ICMP协议 <a class="header-anchor" href="#icmp协议" aria-label="Permalink to &quot;ICMP协议&quot;">​</a></h2><h3 id="icmp协议概念" tabindex="-1">ICMP协议概念 <a class="header-anchor" href="#icmp协议概念" aria-label="Permalink to &quot;ICMP协议概念&quot;">​</a></h3><p>ICMP即互联网控制报文协议（Internet Control Message Protocol ） ，是TCP/IP协议族的网络层协议，常被视为IP协议一部分，用于在IP主机、路由器间传递控制消息 。IP协议尽力而为传输数据，不负责反馈传输中的错误等情况，ICMP则辅助IP协议进行网络质量管理，在IP包出错时汇报错误信息。比如，当路由器无法转发数据包时，可通过ICMP告知发送方 。其消息主要分查询类和差错诊断类，用于网络诊断、检测可达性、报告错误，常见工具ping和traceroute都依赖ICMP 。</p><h3 id="icmp协议报文格式" tabindex="-1">ICMP协议报文格式 <a class="header-anchor" href="#icmp协议报文格式" aria-label="Permalink to &quot;ICMP协议报文格式&quot;">​</a></h3><p><img src="'+g+'" alt=""></p><p>ICMP报文封装在IP数据报中，IP报头在最前，一个ICMP报文含IP报头（至少20字节 ）、ICMP报头（至少8字节 ）和ICMP报文数据部分 。当IP报头协议字段值为1时，表明是ICMP报文，ICMP报头具体如下：</p><ul><li><strong>类型（1字节）</strong>：标识ICMP报文类型，已定义14种 。从类型值分两类，1 - 127为差错报文，如目标不可达、超时；128以上为信息报文 ，如回显请求与应答 。</li><li><strong>代码（1字节）</strong>：与类型字段共同标识ICMP报文详细类型 。如类型值3表示终点不可达，代码值0 - 15对应不同不可达细分情况，像代码0为网络不可达、代码1为主机不可达 。</li><li><strong>校验和（2字节）</strong>：对包括ICMP报文数据部分的整个ICMP数据报计算校验和 ，检测报文传输是否出错，计算方法同IP报头校验和 。</li><li><strong>标识（2字节）</strong>：仅适用于回显请求和应答ICMP报文，标识本ICMP进程，其他如目标不可达、超时ICMP报文该字段值为0 。</li></ul><h3 id="icmp协议报文种类" tabindex="-1">ICMP协议报文种类 <a class="header-anchor" href="#icmp协议报文种类" aria-label="Permalink to &quot;ICMP协议报文种类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分类</th><th>类型值</th><th>代码值</th><th>报文名称</th><th>功能说明</th></tr></thead><tbody><tr><td>差错报告报文</td><td>3</td><td>0</td><td>终点不可达 - 网络不可达</td><td>路由器或主机无法传递数据，因网络不可达时发送</td></tr><tr><td>3</td><td>1</td><td>终点不可达 - 主机不可达</td><td>路由器或主机无法传递数据，因主机不可达时发送</td><td></td></tr><tr><td>3</td><td>2</td><td>终点不可达 - 协议不可达</td><td>路由器或主机无法传递数据，因协议不可达时发送</td><td></td></tr><tr><td>3</td><td>3</td><td>终点不可达 - 端口不可达</td><td>路由器或主机无法传递数据，因连接不存在端口时发送</td><td></td></tr><tr><td>4</td><td>-</td><td>源点抑制</td><td>路由器因网络拥塞，告知发送主机减少数据报流量</td><td></td></tr><tr><td>5</td><td>-</td><td>改变路由（重定向）</td><td>路由器告知发送主机到目标IPv4地址的更好路由</td><td></td></tr><tr><td>11</td><td>0</td><td>超时 - 传输超时</td><td>IP数据报跳数超过生存时间时发送</td><td></td></tr><tr><td>11</td><td>1</td><td>超时 - 分段重组超时</td><td>分段的IP数据报未在期限内重组时发送</td><td></td></tr><tr><td>12</td><td>-</td><td>参数问题</td><td>IP数据报首部参数有问题时发送</td><td></td></tr><tr><td>询问报文（查询类报文）</td><td>8</td><td>-</td><td>回送（Echo）请求</td><td>Ping工具发送此报文检查IPv4连接</td></tr><tr><td>0</td><td>-</td><td>回送（Echo）应答</td><td>目标主机收到回送请求后，正常时返回此报文</td><td></td></tr><tr><td>13</td><td>-</td><td>时间戳（Timestamp）请求</td><td>发送方填充原始时间戳，测试两台主机数据报来回传输时间</td><td></td></tr><tr><td>14</td><td>-</td><td>时间戳（Timestamp）应答</td><td>接收方收到时间戳请求后，填充接收时间戳后返回此报文</td><td></td></tr></tbody></table><h2 id="历年真题-4" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题-4" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网（2019 年）】将物理地址转换为 IP 地址的协议是（ ）A. IPB. ICMPC. ARPD. RARP答案 ：D解析 ：ARP 地址解析协议，用于将 IP 地址转换为物理地址；ICMP 是传输控制协议；RARP 逆向地址解析协议将物理地址转化成网络地址</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2016 年）】ARP 协议的功能是（ ）A. 根据 IP 地址查询 MAC 地址B. 根据 MAC 地址查询 IP 地址C. 根据域名查询 IP 地址D. 根据 IP 地址查询域名答案 ：A解析 ：ARP（地址解析协议）用于在局域网中，根据已知的 IP 地址获取对应的 MAC 地址。B 选项是 RARP 协议的功能；C 和 D 选项是 DNS（域名系统）的功能</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2019 年）】ICMP 协议属于（ ）。A. 网络层协议B. 传输层协议C. 数据链路层协议D. 应用层协议答案 ：A解析 ：ICMP（Internet Control Message Protocol）即网际控制报文协议，是 TCP/IP 协议族的一个子协议，属于网络层协议，用于传输出错报告控制信息，如目的主机或网络不可到达、报文被丢弃、路由阻塞等</th></tr></thead></table><h2 id="ipv6" tabindex="-1">IPv6 <a class="header-anchor" href="#ipv6" aria-label="Permalink to &quot;IPv6&quot;">​</a></h2><h2 id="概念-特点" tabindex="-1">概念&amp;特点 <a class="header-anchor" href="#概念-特点" aria-label="Permalink to &quot;概念&amp;特点&quot;">​</a></h2><p>IPv6 是互联网协议第 6 版，是 IPv4 的 “继任者”，主要解决 IPv4 地址不够用的问题（IPv4 地址像 192.168.1.1，只有约 43 亿个，而全球联网设备早超百亿）。</p><p>IPv6 地址长度是 128 位，数量是 2¹²⁸个，大概够给地球上每粒沙子都分配一个地址，再也不用担心 “门牌不够用”。不用像 IPv4 那样分 A/B/C 类地址，自动支持子网划分（比如企业网、家庭网自己随便分）。自带 “地址自动配置” 功能，设备联网时能自己生成地址，不用手动设置（像手机连 WiFi 自动获取 IP）。现在IPv4地址正逐渐 向 IPv6 进行过度，主要采用以下两种方式：</p><ol><li><p><strong>双协议栈方式</strong> ：在完全过渡到 IPv6 之前，使一部分主机（或路由器）同时运行 IPv4 和 IPv6 两个协议栈，通过双协议进行转换 。</p></li><li><p><strong>隧道技术</strong> ：将整个 IPv6 数据报封装到 IPv4 数据报的数据部分，使 IPv6 数据报可以在 IPv4 网络的隧道中传输</p></li></ol><h2 id="表示方法" tabindex="-1">表示方法 <a class="header-anchor" href="#表示方法" aria-label="Permalink to &quot;表示方法&quot;">​</a></h2><ol><li>采用“冒号十六进制”表示，将 128 位地址分成 8 段，每段 16 位，转换为十六进制并用冒号分隔，例如 2001:0db8:85a3:0000:0000:8a2e:0370:7334 。</li><li>支持零压缩，即连续的零可以用一对冒号取代，例如 FF05:0:0:0:0:0:0:B3 可写成 FF05::B3 。</li><li>支持 CIDR 的斜线表示法，例如 60 位的前缀 2AB0:0000:000D:3000:0000:0000:0000:0000 可记为 2AB0:0000:000D:3000::/60 。</li></ol><h2 id="地址类型" tabindex="-1">地址类型 <a class="header-anchor" href="#地址类型" aria-label="Permalink to &quot;地址类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>地址类型</th><th>核心作用</th><th>典型特征/应用</th></tr></thead><tbody><tr><td>单播地址（Unicast）</td><td>标识单个设备，数据直接定向传输</td><td>全球单播地址：全球唯一，可互联网访问（如网站服务器地址）链路本地地址：局域网内有效，以fe80::开头（设备自动生成）</td></tr><tr><td>组播地址（Multicast）</td><td>标识一组设备，数据发送后组内所有设备接收</td><td>应用：视频会议数据广播、路由器路由信息更新（如OSPFv3） 格式：以ff00::开头（如ff02::1代表链路内所有节点）</td></tr><tr><td>任播地址（Anycast）</td><td>标识一组设备，数据自动发送至网络距离最近的设备</td><td>应用：云服务就近连接（如阿里云服务器）、DDoS防御流量分散特点：地址格式与单播相同，需手动配置设备所属组</td></tr></tbody></table><h2 id="特殊地址" tabindex="-1">特殊地址 <a class="header-anchor" href="#特殊地址" aria-label="Permalink to &quot;特殊地址&quot;">​</a></h2><table tabindex="0"><thead><tr><th>地址类型</th><th>具体地址（含缩写）</th><th>用途说明</th></tr></thead><tbody><tr><td>未指明地址</td><td>16字节全0地址（缩写为“::”）</td><td>仅作为未配置标准IP地址的主机的源地址使用</td></tr><tr><td>环回地址</td><td>0:0:0:0:0:0:0:1（记为“::1”）</td><td>用于主机自身回路测试，仅本机内部通信</td></tr><tr><td>基于IPv4的地址</td><td>前缀为0000:0000:0000:0000:0000:FFFF</td><td>部分地址用作与IPv4兼容的通信地址</td></tr><tr><td>本地链路单播地址</td><td>以fe80::开头</td><td>仅用于局域网内设备之间的通信</td></tr></tbody></table><h2 id="历年真题-5" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题-5" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网（ 2018）】 关于 IPv6，下面的论述中正确的是（ ）。A. IPv6 数据包的首部比 IPv4 复杂B. IPv6 的地址分为单播、广播和任意播 3 种C. 主机拥有的 IPv6 地址是唯一的D. IPv6 地址长度为 128 比特答案 ：D解析 ：IPv6 地址长度为 128 比特，相比 IPv4 的 32 比特地址空间大大增加，解决了地址短缺问题。IPv6 数据包首部相对 IPv4 更加简洁，选项 A 错误；IPv6 没有广播地址，选项 B 错误；主机可以拥有多个 IPv6 地址，选项 C 错误</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2017）】关于 IPv6，下面的论述中不正确的是（ ）。A. IPv6 数据包的首部比 IPv4 复杂B. IPv6 的地址分为单播、广播和任意播 3 种C. 主机拥有的 IPv6 地址是唯一的D. IPv6 地址长度为 128 比特答案 ：ABC解析 ：IPv6 数据包首部进行了简化，选项 A 错误；IPv6 没有广播地址，选项 B 错误；主机可以有多个 IPv6 地址，选项 C 错误；IPv6 地址长度为 128 比特，选项 D 正确。</th></tr></thead></table>',173)])])}const x=a(u,[["render",q]]);export{S as __pageData,x as default};
